args.ReplacementContent:
useEffect(() => {
  if (typeof window !== 'undefined') {
    const saved = localStorage.getItem('7h_crew_schedules');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const cleaned = parsed.filter((item: any) => !item.isDraft && !item.id?.startsWith('show_shift_'));
        if (cleaned.length !== parsed.length) {
          localStorage.setItem('7h_crew_schedules', JSON.stringify(cleaned));
          window.dispatchEvent(new Event('storage'));
          fetch("/api/crew/calendar", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(cleaned)
          }).catch(err => console.error("Failed to sync cleaned schedules:", err));
        }
      } catch {}
    }
  }
}, []);

